package com.mamtrex.hospital.document;
import com.mamtrex.hospital.shared.BaseEntity; import jakarta.persistence.*;
@Entity @Table(name="document_records") public class DocumentRecord extends BaseEntity { private String ownerType; private String ownerId; private String fileName; private String contentType; private String storageKey; protected DocumentRecord(){} public DocumentRecord(String ownerType, String ownerId, String fileName, String contentType, String storageKey){this.ownerType=ownerType; this.ownerId=ownerId; this.fileName=fileName; this.contentType=contentType; this.storageKey=storageKey;} public String getOwnerType(){return ownerType;} public String getOwnerId(){return ownerId;} public String getFileName(){return fileName;} public String getContentType(){return contentType;} public String getStorageKey(){return storageKey;} }
